void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  fragColor = vec4(palette(uv.x + iTime * 0.2), 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec4 a = texture(iChannel0, vec2(uv.x, 1.0 - uv.y));
  fragColor = vec4(a.bgr * (0.5 + 0.5 * uv.y), 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec3 b = texture(iChannel1, uv).rgb;
  vec3 a = texture(iChannel0, uv).rgb;
  fragColor = vec4(mix(a, b, step(0.5, uv.x)) * palette(0.1).r, 1.0);
}
